(() => {
'use strict';
const lessons=[...(window.GERAIS||[]).filter(l=>!/lógico/i.test(l.subject)),...(window.LEGISLACAO||[]),...(window.REGIMENTO||[]),...(window.PESSOAL||[]),...(window.INFORMATICA||[]),...(window.GERAIS||[]).filter(l=>/lógico/i.test(l.subject)),...(window.ESPECIFICOS||[])];
for(const entry of [...(window.QUESTOES_REAIS||[]),...(window.QUESTOES_REAIS_TI||[])]){const lesson=lessons.find(l=>l.id===entry.lessonId);if(lesson)(lesson.realQuestions??=[]).push(entry.question)}
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catalogLesson=lessons.find(l=>l.id==='leg-tecnica');
function normContent(r){return `<p>${esc(r.ementa||'Ementa ainda não localizada.')}</p>${r.link_pdf?`<a class="resource" href="${esc(r.link_pdf)}" target="_blank" rel="noopener">Conferir PDF oficial ${esc(r.numero)}/${esc(r.ano)} ↗</a>`:'<p>Consulte a instituição para confirmar esta referência.</p>'}${r.texto?`<details class="norm-text"><summary>Ler texto da norma aqui · ${r.paginas} páginas no original</summary><p class="notice">Transcrição automática do PDF oficial, sem consolidação adicional. Confira tabelas, redações históricas e alterações no documento original.</p><div class="legal-text">${esc(r.texto)}</div></details>`:''}`}
if(catalogLesson&&window.NORMAS)catalogLesson.sections.push({title:'Acervo oficial dos 65 atos do edital',body:'<p>Fontes consultadas diretamente na API pública da ALEPA em 15/10/2026. Leia os dispositivos abaixo e confronte alterações e revogações. As aulas sobre pessoal explicam as principais regras do quadro funcional, PCCR e participação em eventos; este acervo complementa a leitura e não equivale a uma consolidação jurídica de todos os atos.</p><p>As Resoluções 02/1993, 04/1993 e 04/1995 possuem mais de um registro com assuntos diferentes no acervo. Ambos são apresentados para conferência, sem escolher silenciosamente um deles. A referência 18/2026 do anexo foi corrigida para 18/1989 pela retificação.</p>'+window.NORMAS.map(n=>`<details class="norm-item"><summary>${esc(n.tipo==='Resoluções'?'Resolução':n.tipo)} ${esc(n.numero)}/${esc(n.ano)} ${n.candidates?'· numeração duplicada':''}</summary>${(n.candidates||[n]).map(normContent).join('')}</details>`).join('')});
const key='trilha-alepa-v1'; let state={done:[],answers:{},notes:{},last:null,theme:'light'};
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&typeof saved==='object'){state={...state,...saved};state.done=Array.isArray(saved.done)?saved.done:[];state.answers=saved.answers&&typeof saved.answers==='object'?saved.answers:{};state.notes=saved.notes&&typeof saved.notes==='object'?saved.notes:{}}}catch{}
const persist=()=>{try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('Não foi possível salvar neste navegador. Exporte seu progresso.')}};
const toast=s=>{const t=$('#toast');t.textContent=s;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3500)};
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const subjects=[...new Set(lessons.map(l=>l.subject))];
const icon=s=>/portug/i.test(s)?'Aa':/legis|ética/i.test(s)?'⚖':/lóg/i.test(s)?'∑':/inform/i.test(s)?'▣':'⌘';
const desc=s=>/portug/i.test(s)?'Interpretação, gramática e redação oficial.':/legis|ética/i.test(s)?'Ética pública, normas e processo legislativo.':/lóg/i.test(s)?'Relações lógicas, números e resolução de problemas.':/inform/i.test(s)?'Sistemas, escritório e ferramentas digitais.':'Algoritmos, redes, bancos de dados e software.';
const isDone=l=>state.done.includes(l.id);
const percent=()=>lessons.length?Math.round(100*lessons.filter(isDone).length/lessons.length):0;
function renderNav(){const search=normalize($('#search').value);let current;try{current=decodeURIComponent(location.hash.slice(1))}catch{current="inicio"}const open=[...document.querySelectorAll('.subject[open]')].map(e=>e.dataset.subject);$('#curriculum').innerHTML=subjects.map(s=>{const all=lessons.filter(l=>l.subject===s), list=all.filter(l=>normalize(l.title+' '+l.edital).includes(search));if(!list.length)return '';return `<details class="subject" data-subject="${esc(s)}" ${search||open.includes(s)||list.some(l=>l.id===current)?'open':''}><summary><span class="subject-icon">${icon(s)}</span>${esc(s)}<span class="number">${all.length}</span></summary>${list.map(l=>`<a class="lesson-link ${l.id===current?'active':''}" href="#${esc(l.id)}" ${l.id===current?'aria-current="page"':''}>${isDone(l)?'✓ ':''}${esc(l.title)}</a>`).join('')}</details>`}).join('')||'<p class="empty">Nenhuma aula encontrada. Tente outra palavra.</p>';$('#nav-total').textContent=lessons.length;$('#side-percent').textContent=percent()+'%';$('#side-progress').value=percent();$('#side-count').textContent=`${lessons.filter(isDone).length} de ${lessons.length} aulas concluídas`;}
function dashboard(){const next=lessons.find(l=>l.id===state.last)||lessons.find(l=>!isDone(l))||lessons[0];let attempts=0,correct=0;for(const l of lessons){(l.questions||[]).forEach((q,i)=>{const a=state.answers[l.id+':'+i];if(Number.isInteger(a)){attempts++;if(a===q.answer)correct++}})}$('#crumb').textContent='Visão geral';$('#main').innerHTML=`<div class="heading-row"><div><div class="eyebrow">SEU PRÓXIMO CAPÍTULO COMEÇA AQUI</div><h1>Vamos dar mais um passo?</h1><p class="subtitle">Seu espaço de preparação para a ALEPA. Uma aula de cada vez.</p></div><span class="date-tag">◷ Edital 002/2026 · CETAP</span></div>
<section class="hero"><div><div class="eyebrow">SUA TRILHA · ANALISTA LEGISLATIVO</div><h2>Transforme dedicação<br>em conhecimento.</h2><p>Todo o percurso organizado a partir do seu edital.<br>Estude a teoria, pratique e acompanhe sua evolução.</p><a class="btn" href="#${next?.id||'inicio'}">${state.last?'Continuar estudando':'Começar minha trilha'} <span>→</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="code-card"><span>&lt;seu_futuro&gt;</span><br>&nbsp; foco <b>+</b> constância<br>&nbsp; <b>=</b> evolução;<br>&lt;/seu_futuro&gt;</div><span class="code-label">&lt;/&gt; Programação</span></div></section>
<div class="stats"><div class="stat"><span class="stat-icon">▤</span><div><strong>${lessons.length}</strong><small>Aulas na sua trilha</small></div></div><div class="stat"><span class="stat-icon">✓</span><div><strong>${lessons.filter(isDone).length}</strong><small>Aulas concluídas</small></div></div><div class="stat"><span class="stat-icon">✎</span><div><strong>${attempts}</strong><small>Questões respondidas</small></div></div><div class="stat"><span class="stat-icon">◎</span><div><strong>${attempts?Math.round(correct/attempts*100)+'%':'—'}</strong><small>Taxa de acertos</small></div></div></div>
<div class="dashboard-columns"><section><div class="section-heading"><h2>Seu conteúdo de estudo</h2><span>${subjects.length} disciplinas</span></div><div class="subject-grid">${subjects.map((s,i)=>{const list=lessons.filter(l=>l.subject===s),done=list.filter(isDone).length;return `<a class="subject-card" href="#${(list.find(l=>!isDone(l))||list[0]).id}"><div class="subject-card-top"><span class="tile-icon">${icon(s)}</span><span class="tag">${/program/i.test(s)?'ESPECÍFICOS':'CONHECIMENTOS GERAIS'}</span></div><h3>${esc(s)}</h3><p>${desc(s)}</p><span class="text-link">${list.length} aulas · ${list.reduce((n,l)=>n+l.questions.length,0)} questões <span style="float:right">→</span></span><div class="card-progress"><span>${done} de ${list.length} concluídas</span><span>${Math.round(done/list.length*100)}%</span></div><progress value="${done}" max="${list.length}"></progress></a>`}).join('')}</div></section><aside class="dashboard-aside"><div class="study-tip"><div class="eyebrow">✦ ESTUDE COM INTENÇÃO</div><h3>Pequenos passos.<br>Progresso de verdade.</h3><p>Reserve um momento do dia e siga um ciclo simples:</p><ol><li>Leia a aula e faça suas anotações.</li><li>Resolva as 10 questões autorais.</li><li>Confira os comentários e revise os erros.</li><li>Pratique com as provas de referência.</li></ol></div><div class="source-card"><h3>Seu edital é o ponto de partida</h3><p>Anexo II enviado por você. Conteúdo comum e específicos do cargo 05 — Programação PL.AL.092.</p><a href="edital.pdf" target="_blank" rel="noopener">Abrir documento original ↗</a><br><a href="https://fundacaocetap.selecao.net.br/informacoes/156/" target="_blank" rel="noopener">Publicações oficiais da CETAP ↗</a></div></aside></div>
<details class="coverage"><summary>Escopo, fontes e acompanhamento do material</summary><p class="notice">As aulas são material autoral de apoio organizado pelo anexo. O edital delimita assuntos, mas não permite garantir todas as perguntas possíveis. Consulte as fontes oficiais e as retificações. Questões autorais não são questões oficiais da CETAP.</p><ul>${lessons.map(l=>`<li><a href="#${l.id}">${esc(l.title)}</a> — ${esc(l.edital)}</li>`).join('')}</ul><p class="subtitle">Questões de provas anteriores só são apresentadas como oficiais quando a origem é identificada. Ausências de validação são indicadas na própria aula.</p></details><div class="question-tools"><button class="btn secondary" id="export">Exportar progresso</button><button class="btn secondary" id="import-button">Importar progresso</button><input hidden type="file" id="import" accept="application/json"></div>`;$('#export').onclick=exportState;$('#import').onchange=importState;$('#import-button').onclick=()=>$('#import').click();}
function resource(r,video=false){let vid=null;const url=new URL(r.url);if(video){if(url.hostname==='youtu.be')vid=url.pathname.slice(1);else if(['www.youtube.com','youtube.com'].includes(url.hostname))vid=url.searchParams.get('v')}return `<div class="resource-wrap"><a class="resource ${video?'video':''}" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${video?'<span class="play-icon">▶</span>':''}<span>${esc(r.title)} ↗<small>${video?'Abrir conteúdo externo':esc(url.hostname)}</small></span></a>${vid&&/^[\w-]{11}$/.test(vid)?`<button class="inline-video" data-video="${vid}" data-title="${esc(r.title)}">Assistir nesta página ▷</button><div class="video-player"></div>`:''}</div>`}
function question(q,i,l,real=false){const id=l.id+(real?':real:':':')+i;const selected=state.answers[id];return `<div class="quiz-card" data-question="${esc(id)}"><span class="quiz-label">${real?'PROVA ANTERIOR':'QUESTÃO AUTORAL'} · ${String(i+1).padStart(2,'0')}${real&&q.origin?' · '+esc(q.origin):''}</span><h3>${esc(q.prompt)}</h3><div class="options">${q.options.map((o,j)=>`<button class="option ${!real&&Number.isInteger(selected)?j===q.answer?'correct':j===selected?'wrong':'':j===selected?'selected':''}" data-answer="${j}" ${!real&&Number.isInteger(selected)?'disabled':''}><span class="letter">${'ABCDE'[j]}</span><span>${esc(o)}</span></button>`).join('')}</div><div class="feedback" aria-live="polite">${!real&&Number.isInteger(selected)?feedback(q,selected):''}</div>${real?`<div class="question-tools"><button class="btn secondary" data-reveal>Ver gabarito</button>${q.source?`<a href="${esc(typeof q.source==='string'?q.source:q.source.url)}" target="_blank" rel="noopener">Prova e origem ↗</a>`:''}</div>`:''}</div>`}
function feedback(q,a){return `<div class="explanation ${a===q.answer?'':'incorrect'}"><strong>${a===q.answer?'✓ Você acertou!':Number.isInteger(a)?'Vamos revisar: sua resposta está incorreta.':'Gabarito comentado'} Resposta ${'ABCDE'[q.answer]}.</strong>${Number.isInteger(a)&&a!==q.answer?`Você marcou ${'ABCDE'[a]}: “${esc(q.options[a])}”. `:''}${esc(q.explanation)}${q.gabaritoSource?`<br><a href="${esc(q.gabaritoSource)}" target="_blank" rel="noopener">Conferir documento do gabarito ↗</a>`:''}</div>`}
function lesson(l){state.last=l.id;persist();$('#crumb').textContent=l.subject;const words=l.sections.reduce((n,s)=>n+s.body.replace(/<[^>]*>/g,' ').split(/\s+/).length,0);$('#main').innerHTML=`<header class="lesson-head"><div class="eyebrow">${esc(l.subject)} / AULA ${String(lessons.filter(x=>x.subject===l.subject).indexOf(l)+1).padStart(2,'0')}</div><h1>${esc(l.title)}</h1><div class="lesson-meta"><span class="tag">ALEPA · CARGO 05</span><span>◷ ${Math.max(5,Math.ceil(words/180))} min de leitura</span><span>✎ ${l.questions.length} questões autorais</span><span>${isDone(l)?'✓ Concluída':'Em estudo'}</span></div></header><nav class="lesson-tabs" aria-label="Seções da aula"><a href="#teoria" data-scroll="teoria">Aula</a><a href="#videos" data-scroll="videos">Videoaulas</a><a href="#exercicios" data-scroll="exercicios">Praticar</a><a href="#provas" data-scroll="provas">Provas anteriores</a><a href="#referencias" data-scroll="referencias">Referências</a></nav><div class="lesson-layout"><article class="article"><details class="edital-box"><summary>O que o seu edital exige nesta aula</summary><p>${esc(l.edital)}</p></details><div id="teoria">${l.sections.map((s,i)=>`<section id="section-${i}"><h2>${esc(s.title)}</h2>${s.body}</section>`).join('')}</div><section id="videos"><h2>Aprenda também em vídeo</h2><p class="subtitle">Use as aulas externas para complementar a leitura. A disponibilidade e a cobertura variam por canal.</p>${l.videos.length?l.videos.map(r=>resource(r,true)).join(''):'<p class="notice">Videoaula específica ainda não validada para este tópico. Consulte as referências abaixo.</p>'}</section><section id="exercicios"><div class="section-heading"><h2>Agora é com você</h2><span>10 questões autorais</span></div><p class="subtitle">Marque uma alternativa para receber a correção comentada. Questões de múltipla escolha para praticar o conteúdo; não são provas oficiais.</p><div id="quiz-summary" class="notice"></div>${l.questions.map((q,i)=>question(q,i,l)).join('')}<button class="btn secondary" id="retry">Refazer questões desta aula</button></section><section id="provas"><h2>Provas anteriores</h2>${l.realQuestions?.length?l.realQuestions.map((q,i)=>question(q,i,l,true)).join(''):`<p class="notice">Ainda não há questão de prova anterior com enunciado e gabarito verificados para esta aula. Nenhuma questão autoral foi apresentada como oficial.</p><p>Consulte os documentos originais abaixo. Ao usar provas antigas, confira a versão da ferramenta ou a legislação vigente: uma resposta histórica pode não valer para o edital de 2026.</p><a class="resource" href="https://fundacaocetap.selecao.net.br/" target="_blank" rel="noopener">Acervo e concursos da Fundação CETAP ↗</a>`}</section><section id="referencias"><h2>Fontes para aprofundar</h2>${l.sources.map(r=>resource(r)).join('')}<p class="subtitle">Consulte o recorte do edital e as versões indicadas nas fontes. Material de estudo independente da ALEPA e da banca.</p></section><div class="lesson-bottom"><button class="btn" data-complete>${isDone(l)?'✓ Aula concluída · desmarcar':'Marcar aula como concluída'}</button>${lessons[lessons.indexOf(l)+1]?`<a class="btn secondary" href="#${lessons[lessons.indexOf(l)+1].id}">Próxima aula →</a>`:'<a class="btn secondary" href="#inicio">Voltar ao início</a>'}</div></article><aside class="lesson-aside"><div class="toc"><h3>Nesta aula</h3>${l.sections.map((s,i)=>`<a href="#section-${i}" data-scroll="section-${i}">${esc(s.title)}</a>`).join('')}<a href="#exercicios" data-scroll="exercicios">Praticar o conteúdo →</a></div><div><h3>Suas anotações</h3><textarea class="notes" id="notes" maxlength="50000" aria-label="Anotações desta aula" placeholder="O que você quer lembrar na revisão?">${esc(state.notes[l.id]||'')}</textarea><small class="subtitle">Salvas neste navegador · até 50 mil caracteres.</small><button class="btn secondary" data-complete>${isDone(l)?'✓ Concluída':'Concluir aula'}</button></div></aside></div>`;
document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.scroll)?.scrollIntoView({behavior:'smooth'})});
document.querySelectorAll('[data-video]').forEach(button=>button.onclick=()=>{const frame=document.createElement('iframe');frame.src='https://www.youtube-nocookie.com/embed/'+button.dataset.video;frame.title=button.dataset.title;frame.allow='accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';button.nextElementSibling.replaceChildren(frame);button.remove()});
document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{state.done=isDone(l)?state.done.filter(id=>id!==l.id):[...state.done,l.id];persist();const y=scrollY;lesson(l);renderNav();scrollTo(0,y);toast(isDone(l)?'Aula concluída. Mais um passo na sua trilha!':'Aula marcada para revisar.')});
$('#notes').oninput=e=>{state.notes[l.id]=e.target.value;persist()};
document.querySelectorAll('[data-question]').forEach(card=>{const id=card.dataset.question,real=id.includes(':real:'),i=Number(id.split(':').pop()),q=(real?l.realQuestions:l.questions)[i];card.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const a=Number(b.dataset.answer);state.answers[id]=a;persist();card.querySelectorAll('[data-answer]').forEach((o,j)=>{o.classList.remove('selected','correct','wrong');if(real){o.classList.toggle('selected',j===a)}else{o.disabled=true;if(j===q.answer)o.classList.add('correct');else if(j===a)o.classList.add('wrong')}});card.querySelector('.feedback').innerHTML=real?'':feedback(q,a);updateScore(l)});if(real)card.querySelector('[data-reveal]').onclick=()=>{card.querySelector('.feedback').innerHTML=feedback(q,state.answers[id]);card.querySelectorAll('[data-answer]').forEach((o,j)=>o.classList.toggle('correct',j===q.answer))}});
$('#retry').onclick=()=>{l.questions.forEach((q,i)=>delete state.answers[l.id+':'+i]);persist();const y=scrollY;lesson(l);scrollTo(0,y);toast('Questões reiniciadas para uma nova tentativa.')};updateScore(l);
}
function updateScore(l){const answered=l.questions.filter((q,i)=>Number.isInteger(state.answers[l.id+':'+i])).length,correct=l.questions.filter((q,i)=>state.answers[l.id+':'+i]===q.answer).length;$('#quiz-summary').textContent=`${answered} de ${l.questions.length} respondidas · ${correct} acertos${answered?' · '+Math.round(correct/answered*100)+'% de aproveitamento':''}`}
function exportState(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}));a.download='meu-progresso-alepa.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importState(e){
 const file=e.target.files[0];if(!file)return;
 try{
  if(file.size>20000000)throw Error();
  const s=JSON.parse(await file.text());
  if(s.version!==1||!Array.isArray(s.done)||typeof s.answers!=='object'||!s.answers||typeof s.notes!=='object'||!s.notes)throw Error();
  const next={...state,done:[...new Set(s.done.filter(id=>lessons.some(l=>l.id===id)))],answers:{},notes:{},last:lessons.some(l=>l.id===s.last)?s.last:null};
  for(const l of lessons){
   for(const [list,prefix]of [[l.questions||[],':'],[l.realQuestions||[],':real:']])list.forEach((q,i)=>{const id=l.id+prefix+i,a=s.answers[id];if(Number.isInteger(a)&&a>=0&&a<q.options.length)next.answers[id]=a});
   if(typeof s.notes[l.id]==='string'){if(s.notes[l.id].length>50000)throw Error();next.notes[l.id]=s.notes[l.id]}
  }
  state=next;persist();route();toast('Progresso importado. Bons estudos!');
 }catch{toast('Arquivo inválido. Use um progresso exportado por este site (até 20 MB e 50 mil caracteres por anotação).')}
}
function sidebarAccess(){const hidden=innerWidth<=850&&!$('#sidebar').classList.contains('open');$('#sidebar').inert=hidden}
function menu(open){$('#sidebar').classList.toggle('open',open);$('#shade').classList.toggle('visible',open);$('#menu-toggle').setAttribute('aria-expanded',String(open));sidebarAccess();if(open)$('#search').focus();else $('#menu-toggle').focus()}
function metadata(){const box=document.createElement('section');box.className='exam-notice';box.innerHTML='<strong>Seu edital, conferido.</strong> Prova objetiva: 10 questões de Português, 10 de Legislação e Ética, 5 de Informática, 5 de Raciocínio Lógico e 20 de Conhecimentos Específicos. Cinco alternativas por questão. <a href="https://anexos-r2.selecao.net.br/uploads/237/concursos/156/anexos/8997e283-4a70-47a1-92d0-393d59711e32.pdf" target="_blank" rel="noopener">Edital, item 11 ↗</a><br><strong>Retificação aplicada:</strong> Resolução 18/2026 do anexo original deve ser lida como <strong>18/1989</strong>. <a href="https://anexos-r2.selecao.net.br/uploads/237/concursos/156/anexos/87d439ce-eac5-4a39-9ce3-61e48ed2eccb.pdf" target="_blank" rel="noopener">Retificação 002, item 3 ↗</a> As regras de vigência do edital excluem alterações legislativas posteriores à sua publicação.';$('#main .coverage').before(box)}
function route(){let id;try{id=decodeURIComponent(location.hash.slice(1))}catch{id='inicio'}const l=lessons.find(l=>l.id===id);if(l)lesson(l);else{dashboard();metadata()}renderNav();$('#sidebar').classList.remove('open');$('#shade').classList.remove('visible');$('#menu-toggle').setAttribute('aria-expanded','false');sidebarAccess();scrollTo(0,0)}
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();scrollTo(0,0)};$('#search').oninput=renderNav;$('#menu-toggle').onclick=()=>menu(true);$('#close-menu').onclick=()=>menu(false);$('#shade').onclick=()=>menu(false);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#sidebar').classList.contains('open'))menu(false);if(e.key==='Tab'&&$('#sidebar').classList.contains('open')){const nodes=[...$('#sidebar').querySelectorAll('a,button,input,summary')].filter(x=>x.getClientRects().length);if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus()}}});
document.body.classList.toggle('dark',state.theme==='dark');$('#theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';document.body.classList.toggle('dark',state.theme==='dark');persist()};window.addEventListener('hashchange',route);window.addEventListener('resize',sidebarAccess);route();
})();
